.manifesto{padding:90px 0;display:grid;grid-template-columns:.7fr 1.3fr;gap:70px;border-bottom:1px solid var(--line)}.manifesto blockquote{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:clamp(2rem,4.2vw,4.3rem);line-height:1.02;margin:0}.manifesto blockquote em{color:var(--orange);font-style:normal}.manifesto p{margin:0;color:var(--paper2);max-width:520px}.counter{display:grid;grid-template-columns:repeat(3,1fr);margin-top:38px;border-top:1px solid var(--line)}.counter div{padding:15px 5px;border-right:1px solid var(--line)}.counter div:last-child{border:0}.counter strong{display:block;font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:2.5rem;color:var(--lime)}.counter small{text-transform:uppercase;letter-spacing:.12em;color:var(--muted)}
.trial{padding:100px 0;border-bottom:1px solid var(--line);position:relative}.trial-grid{display:grid;grid-template-columns:minmax(0,.86fr) minmax(0,1.25fr);gap:clamp(40px,8vw,110px);align-items:center}.trial:nth-of-type(even) .trial-grid{grid-template-columns:minmax(0,1.25fr) minmax(0,.86fr)}.trial:nth-of-type(even) .lab{order:-1}.num{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;color:var(--orange);font-size:1.1rem}.trial h2{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:clamp(2.6rem,6vw,5.6rem);line-height:.87;letter-spacing:-.05em;margin:14px 0 23px}.trial-copy p{color:var(--paper2);max-width:450px}.status{margin-top:26px;display:inline-flex;gap:10px;align-items:center;text-transform:uppercase;letter-spacing:.12em;font-size:.72rem;color:var(--muted)}.status i{display:block;width:10px;height:10px;border:1px solid var(--muted);border-radius:50%}.status.passed{color:var(--lime)}.status.passed i{background:var(--lime);border-color:var(--lime);box-shadow:0 0 18px var(--lime)}
.lab{position:relative;background:#201f1b;border:1px solid #565044;padding:clamp(18px,4vw,38px);box-shadow:18px 18px 0 #090a08}.lab:before{content:"";position:absolute;inset:8px;border:1px dashed rgba(239,229,210,.15);pointer-events:none}.plate{position:relative;background:var(--paper);color:var(--ink);padding:12px 16px;text-transform:uppercase;letter-spacing:.13em;font-size:.66rem;display:flex;justify-content:space-between;margin-bottom:22px}.screws:after{content:"⊙  ⊙";color:#766e61}.btn{border:1px solid var(--paper);background:transparent;color:var(--paper);padding:13px 17px;text-transform:uppercase;letter-spacing:.09em;font-size:.74rem;cursor:pointer;transition:.15s}.btn:hover,.btn:focus-visible{background:var(--paper);color:var(--ink)}.btn.hot{background:var(--orange);border-color:var(--orange);color:#17130f;font-weight:500}.btn.hot:hover{filter:brightness(1.15)}
.speed-stage{height:310px;display:grid;place-items:center;position:relative;overflow:hidden;background:radial-gradient(circle at 50% 45%,#34342e,#151613 65%);border:1px solid #4b483f}.speed-stage.ready{cursor:crosshair}.speed-stage.go{background:radial-gradient(circle at 50% 45%,#518e8d,#112b2b 62%)}.signal{width:158px;height:158px;border-radius:50%;display:grid;place-items:center;border:2px solid #625f55;box-shadow:inset 0 0 0 15px #1a1b18,0 10px 50px #000;background:#252620;color:var(--muted);font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:1.35rem;text-align:center;transition:.12s}.go .signal{background:var(--cyan);color:#0d2525;border-color:#d9ffff;box-shadow:inset 0 0 0 15px #224748,0 0 60px rgba(88,204,209,.6);transform:scale(1.04)}.speed-result{position:absolute;bottom:17px;left:18px;right:18px;display:flex;justify-content:space-between;color:var(--muted);font-size:.72rem}.speed-result strong{color:var(--paper);font-size:1rem}.controls{display:flex;gap:11px;flex-wrap:wrap;margin-top:16px}
.terminal{background:#090d0c;border:1px solid #43645f;min-height:330px;padding:20px;color:#8be5c8;box-shadow:inset 0 0 45px rgba(63,191,157,.07)}.termhead{display:flex;justify-content:space-between;color:#5e8e80;font-size:.69rem;border-bottom:1px solid #203c34;padding-bottom:10px}.prompt{margin:24px 0 16px;color:#d1eadf}.commandline{min-height:57px;padding:12px;border:1px solid #315c50;background:#0c1512;display:flex;align-items:center;gap:6px;flex-wrap:wrap}.commandline:before{content:"$";color:var(--lime)}.slot-placeholder{color:#3e665a}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:17px}.chip{background:#16251f;color:#9be7cf;border:1px solid #3d705f;padding:9px 11px;cursor:pointer;font-size:.75rem}.chip:hover{border-color:var(--lime);color:var(--lime)}.chip.used{opacity:.28;pointer-events:none}.term-msg{min-height:42px;margin-top:17px;font-size:.77rem;color:#6f9e90}.term-msg.good{color:var(--lime)}
.design-bench{display:grid;grid-template-columns:1.2fr .8fr;gap:24px}.poster{min-height:340px;background:#e6dbc7;position:relative;overflow:hidden;box-shadow:inset 0 0 0 1px #fff;--h:190;--gap:28px;--round:20px}.poster:before{content:"FORM /  FUNCTION";position:absolute;top:23px;left:24px;color:#262620;font-size:.62rem;letter-spacing:.16em}.shape{position:absolute;transition:.25s ease;background:hsl(var(--h) 62% 50%)}.s1{width:47%;height:41%;left:10%;top:25%;border-radius:var(--round) 50% var(--round) 50%;transform:translateX(calc((var(--gap) - 28px)*-.25)) rotate(-8deg)}.s2{width:35%;height:55%;right:8%;bottom:6%;border-radius:50% var(--round) 50% var(--round);background:#1d1e1b;transform:translateX(calc((var(--gap) - 28px)*.25)) rotate(12deg)}.s3{height:5px;left:9%;right:9%;bottom:13%;background:var(--orange);transform:rotate(-4deg)}.poster small{position:absolute;bottom:18px;left:24px;color:#34342e;letter-spacing:.1em}.knobs label{display:block;margin-bottom:24px;color:var(--paper2);font-size:.72rem;text-transform:uppercase;letter-spacing:.1em}.knobs input{display:block;width:100%;margin-top:10px;accent-color:var(--orange)}.beauty-score{border-top:1px solid var(--line);padding-top:18px;margin-top:6px}.beauty-score strong{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;color:var(--orange);font-size:2.5rem}
.verdict{padding:110px 0;background:var(--paper);color:var(--ink);text-align:center}.seal{width:110px;height:110px;margin:0 auto 27px;border:2px solid var(--ink);border-radius:50%;display:grid;place-items:center;font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:3rem;box-shadow:inset 0 0 0 7px var(--paper),inset 0 0 0 9px var(--ink);transform:rotate(-7deg)}.verdict h2{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:clamp(3rem,7vw,7rem);line-height:.9;letter-spacing:-.055em;margin:0}.verdict p{max-width:580px;margin:25px auto;color:#504b42}.scoreline{display:flex;justify-content:center;gap:clamp(25px,7vw,90px);margin:38px 0}.scoreline strong{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:2.3rem;display:block}.scoreline small{text-transform:uppercase;letter-spacing:.12em}.verdict .btn{border-color:var(--ink);color:var(--ink)}.verdict .btn:hover{background:var(--ink);color:var(--paper)}
footer{padding:38px 0;color:var(--muted);font-size:.74rem}.foot{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}footer a:hover{color:var(--cyan)}
