<body>
<div class="grain"></div>
<header class="hero">
  <div class="shell hero-copy">
    <div class="eyebrow">A three-part proving ground</div>
    <h1>Merit <span>Trials</span></h1>
    <p class="dek">In 2010 Jon switched computers and found three things worth caring about: speed, Unixy goodness, and beauty. Enter the lab. Put all three on the bench.</p>
    <a class="start" href="#briefing">Begin inspection <b>↓</b></a>
  </div>
</header>
<main>
  <section class="shell manifesto" id="briefing">
    <div class="eyebrow">The inspection brief / 01</div>
    <div>
      <blockquote>Good tools should feel <em>swift</em>, speak the language of power, and leave the room prettier.</blockquote>
      <p style="margin-top:28px">Three compact trials await. Each earns a brass merit stamp. There are no spec sheets here, only the qualities you can actually feel.</p>
      <div class="counter"><div><strong>01</strong><small>Reflex</small></div><div><strong>02</strong><small>Command</small></div><div><strong>03</strong><small>Form</small></div></div>
    </div>
  </section>

  <section class="trial" id="speed">
    <div class="shell trial-grid">
      <div class="trial-copy"><span class="num">01 / SPEED</span><h2>The Wake Test</h2><p>A computer that is ready before your train of thought wanders off is not merely fast. It is polite. Arm the signal, wait for cyan, then strike it as quickly as you can.</p><div class="status" id="speedStatus"><i></i><span>Merit stamp pending</span></div></div>
      <div class="lab"><div class="plate"><span>Reaction chamber · ms</span><span class="screws"></span></div><div class="speed-stage" id="speedStage" role="button" tabindex="0" aria-label="Reaction speed test"><div class="signal" id="signal">Stand by</div><div class="speed-result"><span>Human wake latency</span><strong id="speedReadout">— ms</strong></div></div><div class="controls"><button class="btn hot" id="armBtn">Arm the test</button><button class="btn" id="speedReset">Reset</button></div></div>
    </div>
  </section>

  <section class="trial" id="unix">
    <div class="shell trial-grid">
      <div class="trial-copy"><span class="num">02 / UNIXY GOODNESS</span><h2>Pipe Works</h2><p>The useful sort of power is composable. Build three tiny commands from ordinary parts and send their output flowing into the next tool.</p><div class="status" id="unixStatus"><i></i><span>0 of 3 lines flowing</span></div></div>
      <div class="lab"><div class="plate"><span>Command conduit · sh</span><span class="screws"></span></div><div class="terminal"><div class="termhead"><span>MERIT-OS 10.6</span><span>PIPE PRESSURE: NOMINAL</span></div><div class="prompt" id="taskText"></div><div class="commandline" id="commandLine"><span class="slot-placeholder">choose parts below…</span></div><div class="chips" id="chips"></div><div class="term-msg" id="termMsg">Build the command from left to right.</div></div><div class="controls"><button class="btn" id="undoChip">Undo</button><button class="btn hot" id="runCommand">Run line ↵</button></div></div>
    </div>
  </section>

  <section class="trial" id="beauty">
    <div class="shell trial-grid">
      <div class="trial-copy"><span class="num">03 / BEAUTY</span><h2>The Quiet Object</h2><p>Beauty is not frosting. It is the moment the parts stop arguing. Tune the colour, breathing room, and softness until the composition feels settled, then trust your eye.</p><div class="status" id="beautyStatus"><i></i><span>Awaiting your eye</span></div></div>
      <div class="lab"><div class="plate"><span>Form calibration · subjective</span><span class="screws"></span></div><div class="design-bench"><div class="poster" id="poster"><div class="shape s1"></div><div class="shape s2"></div><div class="shape s3"></div><small>CALIBRATION PRINT / 03</small></div><div class="knobs"><label>Colour temperature<input id="hue" type="range" min="160" max="215" value="190"></label><label>Breathing room<input id="gap" type="range" min="0" max="56" value="28"></label><label>Edge character<input id="round" type="range" min="0" max="70" value="20"></label><div class="beauty-score"><small>Visual tension</small><br><strong id="tension">42</strong><small> / 100</small></div><button class="btn hot" id="approveBeauty" style="margin-top:17px;width:100%">This feels right</button></div></div></div>
    </div>
  </section>

  <section class="verdict" id="verdict"><div class="shell"><div class="seal" id="seal">?</div><div class="eyebrow" style="color:#6d6253">Final inspection</div><h2 id="verdictTitle">The jury is still out.</h2><p id="verdictText">Complete all three trials and the laboratory will issue its gloriously unofficial verdict.</p><div class="scoreline"><div><strong id="scoreSpeed">—</strong><small>Speed</small></div><div><strong id="scoreUnix">0/3</strong><small>Unix</small></div><div><strong id="scoreBeauty">—</strong><small>Beauty</small></div></div><button class="btn" id="resetAll">Reopen the lab</button></div></section>
</main>
<footer><div class="shell foot"><a href="index.php">← Chloe Reads Jon</a><span>Inspired by Jon's <a href="https://jona.ca/2010/05/3-reasons-i-like-mac.html">“3 Reasons I Like The Mac”</a></span></div></footer>
<script>
const state={speed:null,unix:0,beauty:null};
const $=s=>document.querySelector(s);
let timer=null,armedAt=0,phase='idle';
function tone(freq=440,d=.08){try{const c=new (window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),g=c.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.05,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+d);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+d)}catch(e){}}
function setStatus(id,text,pass=false){const el=$(id);el.querySelector('span').textContent=text;el.classList.toggle('passed',pass)}
function arm(){clearTimeout(timer);phase='waiting';$('#speedStage').className='speed-stage ready';$('#signal').textContent='Wait…';$('#speedReadout').textContent='— ms';timer=setTimeout(()=>{phase='go';armedAt=performance.now();$('#speedStage').className='speed-stage go';$('#signal').textContent='NOW';tone(760,.09)},900+Math.random()*1900)}
function strike(){if(phase==='waiting'){clearTimeout(timer);phase='idle';$('#signal').textContent='Too soon';$('#speedStage').className='speed-stage';$('#speedReadout').textContent='false start';tone(130,.16);return}if(phase!=='go')return;const ms=Math.round(performance.now()-armedAt);phase='done';state.speed=ms;$('#speedStage').className='speed-stage';$('#signal').textContent=ms<260?'Quick!':ms<420?'Awake':'Coffee?';$('#speedReadout').textContent=ms+' ms';setStatus('#speedStatus',ms<300?'Speed merit awarded':'Speed trial complete',true);$('#scoreSpeed').textContent=ms+'ms';tone(520,.12);setTimeout(()=>tone(780,.13),80);updateVerdict()}
$('#armBtn').onclick=arm;$('#speedStage').onclick=strike;$('#speedStage').onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();strike()}};$('#speedReset').onclick=()=>{clearTimeout(timer);phase='idle';state.speed=null;$('#speedStage').className='speed-stage';$('#signal').textContent='Stand by';$('#speedReadout').textContent='— ms';$('#scoreSpeed').textContent='—';setStatus('#speedStatus','Merit stamp pending');updateVerdict()};
const rounds=[
 {task:'Find every note containing the word “wonder”.',parts:['grep','-ril','"wonder"','.'],answer:['grep','-ril','"wonder"','.'],noise:['sort','*.png']},
 {task:'List log files, then count the lines.',parts:['find','.','-name','"*.log"','|','wc','-l'],answer:['find','.','-name','"*.log"','|','wc','-l'],noise:['rm','open']},
 {task:'Show the five largest folders in human units.',parts:['du','-sh','*','|','sort','-hr','|','head','-5'],answer:['du','-sh','*','|','sort','-hr','|','head','-5'],noise:['cat','-x']}
];let picked=[];
function loadRound(){const r=rounds[state.unix];if(!r)return;$('#taskText').textContent=r.task;picked=[];renderLine();const all=[...r.parts,...r.noise].sort(()=>Math.random()-.5);$('#chips').innerHTML='';all.forEach((p,i)=>{const b=document.createElement('button');b.className='chip';b.textContent=p;b.dataset.id=i;b.onclick=()=>{picked.push({p,b});b.classList.add('used');renderLine()};$('#chips').appendChild(b)});$('#termMsg').className='term-msg';$('#termMsg').textContent='Build the command from left to right.'}
function renderLine(){const el=$('#commandLine');el.innerHTML='';if(!picked.length){el.innerHTML='<span class="slot-placeholder">choose parts below…</span>';return}picked.forEach(x=>{const s=document.createElement('span');s.textContent=x.p;el.appendChild(s)})}
$('#undoChip').onclick=()=>{const x=picked.pop();if(x)x.b.classList.remove('used');renderLine()};
$('#runCommand').onclick=()=>{if(state.unix>=3)return;const ok=JSON.stringify(picked.map(x=>x.p))===JSON.stringify(rounds[state.unix].answer);if(!ok){$('#termMsg').className='term-msg';$('#termMsg').textContent='⚠ No flow. Check the order and try again.';tone(150,.13);return}state.unix++;tone(430,.08);setTimeout(()=>tone(650,.08),70);$('#scoreUnix').textContent=state.unix+'/3';setStatus('#unixStatus',state.unix===3?'Unix merit awarded':state.unix+' of 3 lines flowing',state.unix===3);$('#termMsg').className='term-msg good';$('#termMsg').textContent='✓ Output flowing cleanly.';if(state.unix<3)setTimeout(loadRound,850);else{$('#taskText').textContent='All conduits are open.';$('#chips').innerHTML='';$('#commandLine').innerHTML='<span>echo "Unixy goodness confirmed"</span>';updateVerdict()}};
loadRound();
function tune(){const h=$('#hue').value,g=$('#gap').value,r=$('#round').value;$('#poster').style.setProperty('--h',h);$('#poster').style.setProperty('--gap',g+'px');$('#poster').style.setProperty('--round',r+'px');const raw=Math.abs(h-184)*.65+Math.abs(g-36)*.7+Math.abs(r-34)*.45;const t=Math.max(9,Math.min(88,Math.round(18+raw)));$('#tension').textContent=t;state.beauty=null;$('#scoreBeauty').textContent='—';setStatus('#beautyStatus','Awaiting your eye');updateVerdict()}
['hue','gap','round'].forEach(id=>$('#'+id).oninput=tune);tune();
$('#approveBeauty').onclick=()=>{const t=Number($('#tension').textContent);state.beauty=Math.max(62,104-t);$('#scoreBeauty').textContent=state.beauty+'%';setStatus('#beautyStatus','Beauty merit awarded',true);tone(392,.12);setTimeout(()=>tone(523,.15),90);updateVerdict()};
function updateVerdict(){if(state.speed===null||state.unix<3||state.beauty===null){$('#seal').textContent='?';$('#verdictTitle').textContent='The jury is still out.';$('#verdictText').textContent='Complete all three trials and the laboratory will issue its gloriously unofficial verdict.';return}const s=Math.max(40,Math.min(100,Math.round(120-state.speed/5)));const total=Math.round((s+state.beauty+100)/3);$('#seal').textContent=total;$('#verdictTitle').textContent=total>=88?'A tool with manners.':total>=73?'Three merits, well earned.':'Beautifully imperfect.';$('#verdictText').textContent=`Final merit index: ${total}/100. Fast enough to protect attention, powerful enough to reward curiosity, and composed enough to deserve a place in the room.`;$('#verdict').scrollIntoView({behavior:'smooth',block:'center'})}
$('#resetAll').onclick=()=>location.reload();
</script>
</body>
</html>
